import {derive,seal,open} from './crypto.js';
const $=id=>document.getElementById(id),STORE='cofre-local:v1',defaults=['Pessoal','Trabalho','Finanças','Redes sociais','Outros'];
let key=null,salt=null,items=[],category='',editing=null,revision=null,session=0,busy=false,lastActivity=Date.now(),toastTimer;
function notify(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4000)}
function gate(){try{const exists=!!localStorage.getItem(STORE);$('gate-title').textContent=exists?'Bem-vindo de volta':'Crie seu cofre';$('gate-desc').textContent=exists?'Digite sua senha mestra para abrir seus acessos.':'Escolha uma senha mestra para proteger seus acessos.';$('gate-submit').textContent=exists?'Desbloquear cofre':'Criar cofre';$('confirm-label').hidden=exists;$('confirm-master').required=!exists;$('master').minLength=exists?1:12;$('master').autocomplete=exists?'current-password':'new-password';}catch{$('gate-error').textContent='O armazenamento está indisponível neste navegador.';$('gate-submit').disabled=true}}
function lock(message){session++;key=null;salt=null;items=[];revision=null;editing=null;$('workspace').hidden=true;$('gate').hidden=false;$('entries').replaceChildren();$('categories').replaceChildren();$('search').value='';$('category-title').textContent='Todas as senhas';$('result-count').textContent='';$('total').textContent='0';$('category-options').replaceChildren();category='';document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('entry-form').reset();$('restore-form').reset();$('gate-form').reset();gate();if(message)notify(message)}
function unlocked(data,raw){key=data.key;salt=data.salt;items=data.items;revision=raw;lastActivity=Date.now();$('gate-form').reset();$('gate').hidden=true;$('workspace').hidden=false;render()}
async function persist(next){if(!key||busy)throw Error('Aguarde e tente novamente.');busy=true;const current=session;try{const blob=JSON.stringify(await seal(next,key,salt));if(current!==session||!key)throw Error('Cofre bloqueado. Abra novamente.');if(localStorage.getItem(STORE)!==revision){lock();throw Error('O cofre mudou em outra aba. Abra novamente.')}localStorage.setItem(STORE,blob);revision=blob;items=next;render()}finally{busy=false}}
$('gate-form').addEventListener('submit',async e=>{e.preventDefault();$('gate-error').textContent='';$('gate-submit').disabled=true;const current=session;try{if(!crypto.subtle)throw Error('Abra o site por HTTPS para usar a criptografia.');const raw=localStorage.getItem(STORE),password=$('master').value;let data;if(raw){try{data=await open(JSON.parse(raw),password)}catch{throw Error('Senha mestra incorreta ou cofre danificado.')}}else{if(password.length<12)throw Error('Use pelo menos 12 caracteres.');if(password!==$('confirm-master').value)throw Error('As senhas não são iguais.');const s=crypto.getRandomValues(new Uint8Array(16));data={key:await derive(password,s),salt:s,items:[]}}if(current!==session)return;if(localStorage.getItem(STORE)!==raw)throw Error('O cofre mudou em outra aba. Tente novamente.');const stored=raw||JSON.stringify(await seal([],data.key,data.salt));if(current!==session)return;if(!raw){if(localStorage.getItem(STORE)!==null)throw Error('Um cofre já foi criado em outra aba.');localStorage.setItem(STORE,stored)}unlocked(data,stored)}catch(err){$('gate-error').textContent=err.message}finally{$('gate-submit').disabled=false}});
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function button(text,handler,cls){const b=el('button',cls,text);b.type='button';b.addEventListener('click',handler);return b}
function render(){const cats=[...new Set([...defaults,...items.map(e=>e.category)])];$('categories').replaceChildren();for(const c of ['',...cats]){const b=button(c||'Todas as senhas',()=>{category=c;render()},category===c?'active':'');b.append(el('span','',String(c?items.filter(e=>e.category===c).length:items.length)));$('categories').append(b)}$('category-options').replaceChildren(...cats.map(c=>{const o=document.createElement('option');o.value=c;return o}));$('total').textContent=items.length;$('category-title').textContent=category||'Todas as senhas';const q=$('search').value.toLocaleLowerCase('pt-BR').trim();const shown=items.filter(e=>(!category||e.category===category)&&[e.title,e.username,e.url].some(v=>v.toLocaleLowerCase('pt-BR').includes(q))).sort((a,b)=>a.title.localeCompare(b.title,'pt-BR'));$('result-count').textContent=`${shown.length} ${shown.length===1?'acesso':'acessos'}`;$('entries').replaceChildren();if(!shown.length){const n=el('div','empty');n.append(el('div','empty-icon','◇'),el('h3','',items.length?'Nenhuma senha encontrada':'Seu cofre começa aqui'),el('p','',items.length?'Tente outra pesquisa ou escolha uma categoria diferente.':'Adicione seu primeiro acesso e deixe suas senhas organizadas.'),button(items.length?'Limpar filtros':'+ Adicionar primeira senha',()=>{if(items.length){category='';$('search').value='';render()}else edit()},'primary'));$('entries').append(n)}for(const e of shown){const card=el('article','entry'),head=el('div','entry-heading'),titles=el('div');titles.append(el('h3','',e.title),el('small','',e.category));head.append(el('div','entry-avatar',e.title.slice(0,1).toUpperCase()),titles);const secret=el('div','secret'),code=el('code','','••••••••••••');let visible=false,timer;const show=button('Mostrar',()=>{visible=!visible;clearTimeout(timer);code.textContent=visible?e.password:'••••••••••••';show.textContent=visible?'Ocultar':'Mostrar';if(visible)timer=setTimeout(()=>{visible=false;code.textContent='••••••••••••';show.textContent='Mostrar'},15000)});secret.append(code,show);const actions=el('div','entry-actions');actions.append(button('Copiar',async()=>{try{await navigator.clipboard.writeText(e.password);notify('Senha copiada. Limpe a área de transferência após usar.')}catch{notify('Não foi possível copiar. Use Mostrar para copiar manualmente.')}}),button('Editar',()=>edit(e)),button('Excluir',async()=>{if(!confirm(`Excluir a senha de ${e.title}?`))return;try{await persist(items.filter(v=>v.id!==e.id));notify('Senha excluída.')}catch(err){notify(err.message)}},'delete'));card.append(head,el('p','entry-user',e.username||'Sem usuário'),secret);if(e.url)card.append(el('p','entry-notes',e.url));if(e.notes)card.append(el('p','entry-notes',e.notes));card.append(actions);$('entries').append(card)}}
function edit(entry){editing=entry?.id||null;$('entry-form').reset();$('entry-error').textContent='';$('editor-title').textContent=entry?'Editar senha':'Nova senha';for(const name of ['title','username','password','url','category','notes'])$('entry-form').elements[name].value=entry?.[name]||(name==='category'?(category||'Pessoal'):'');$('entry-form').elements.password.type='password';$('toggle-entry').textContent='Mostrar';$('editor').showModal()}
$('entry-form').addEventListener('submit',async e=>{e.preventDefault();$('entry-error').textContent='';$('save-entry').disabled=true;try{const f=$('entry-form').elements;const entry={id:editing||crypto.randomUUID(),title:f.title.value.trim(),username:f.username.value.trim(),password:f.password.value,url:f.url.value.trim(),category:f.category.value.trim(),notes:f.notes.value.trim()};if(!entry.title||!entry.category)throw Error('Preencha nome e categoria.');await persist(editing?items.map(v=>v.id===editing?entry:v):[...items,entry]);$('editor').close();$('entry-form').reset();notify('Senha salva neste navegador.')}catch(err){$('entry-error').textContent=err.message}finally{$('save-entry').disabled=false}});
$('toggle-entry').onclick=()=>{const p=$('entry-form').elements.password;p.type=p.type==='password'?'text':'password';$('toggle-entry').textContent=p.type==='password'?'Mostrar':'Ocultar'};
$('editor').addEventListener('close',()=>$('entry-form').reset());$('close-editor').onclick=()=>$('editor').close();$('add').onclick=()=>edit();$('search').oninput=render;$('lock').onclick=()=>lock();
$('export').onclick=()=>{try{const raw=localStorage.getItem(STORE);if(!raw)throw Error();const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`cofre-local-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup criptografado exportado.')}catch{notify('Não foi possível exportar.')}};
function restoreDialog(){$('restore-form').reset();$('restore-error').textContent='';$('restore-dialog').showModal()}
$('restore').onclick=restoreDialog;$('restore-gate').onclick=restoreDialog;$('close-restore').onclick=()=>$('restore-dialog').close();$('restore-dialog').addEventListener('close',()=>$('restore-form').reset());
$('restore-form').onsubmit=async e=>{e.preventDefault();$('restore-error').textContent='';$('restore-submit').disabled=true;const current=session;try{const before=localStorage.getItem(STORE),file=$('backup-file').files[0];if(!file||file.size>10000000)throw Error('Escolha um backup de até 10 MB.');const data=JSON.parse(await file.text());let decoded;try{decoded=await open(data,$('backup-master').value)}catch{throw Error('Backup inválido ou senha mestra incorreta.')}if(current!==session)throw Error('A sessão mudou. Tente novamente.');if(busy||localStorage.getItem(STORE)!==before)throw Error('O cofre mudou. Tente novamente.');if(before&&!confirm('Substituir o cofre atual pelo backup validado?'))return;const raw=JSON.stringify(data);localStorage.setItem(STORE,raw);session++;unlocked(decoded,raw);$('restore-dialog').close();notify('Backup restaurado.')}catch(err){$('restore-error').textContent=err.message||'Não foi possível restaurar.'}finally{$('restore-submit').disabled=false}};
for(const event of ['pointerdown','keydown','scroll'])document.addEventListener(event,()=>{if(key&&Date.now()-lastActivity>=300000){lock('Cofre bloqueado por inatividade.');return}lastActivity=Date.now()},{passive:true,capture:true});setInterval(()=>{if(key&&Date.now()-lastActivity>=300000)lock('Cofre bloqueado por inatividade.')},1000);document.addEventListener('visibilitychange',()=>{if(document.hidden&&key)lock()});window.addEventListener('pagehide',()=>lock());window.addEventListener('storage',e=>{if(e.key===STORE||e.key===null){lock('O cofre mudou em outra aba. Abra novamente.')}});gate();
